"""Plain lending controls. Untrusted names and terms are always text, never markup."""


def render_lend_fragment():
    return r'''<style>
.vl-root{max-width:780px;display:flex;flex-direction:column;gap:14px;min-width:0}
.vl-root *{box-sizing:border-box}.vl-root label{display:flex;flex-direction:column;gap:6px}
.vl-root input,.vl-root textarea,.vl-root select{background:var(--bg,#16171a);color:var(--ink,#eee);border:1px solid var(--border,#555);border-radius:7px;padding:9px;font:inherit;min-width:0;width:100%}
.vl-root input[type=checkbox]{width:auto;flex:none}.vl-check{display:flex!important;flex-direction:row!important;align-items:flex-start;gap:8px}
.vl-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:12px}.vl-root fieldset{border:1px solid var(--border,#555);border-radius:9px;padding:16px;min-width:0;display:flex;flex-direction:column;gap:12px}
.vl-root legend{padding:0 6px}.vl-peer-pin{direction:ltr;unicode-bidi:isolate;overflow-wrap:anywhere}.vl-warning{padding:12px;border:1px solid var(--warn,#a18341);border-radius:9px;line-height:1.5}
.vl-mode[aria-pressed=true]{border-color:var(--ink,#ddd);background:var(--panel,#3b4142)}.vl-status{min-height:24px;white-space:pre-wrap;overflow-wrap:anywhere}.vl-actions{display:flex;flex-wrap:wrap;gap:8px}
.vl-card{border:1px solid var(--border,#555);padding:12px;border-radius:8px;display:flex;flex-direction:column;gap:10px;overflow-wrap:anywhere}
.vl-root dl{display:grid;grid-template-columns:minmax(100px,1fr) minmax(100px,1fr);gap:8px;margin:8px 0}.vl-root dt,.vl-root dd{margin:0;overflow-wrap:anywhere}
.vl-root img{display:block;max-width:100%;height:auto;background:white;padding:10px;border-radius:8px}.vl-root pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px}.vl-root [hidden]{display:none!important}
</style><script>
(function(){
if(window.VoolLend)return;
function t(k){return typeof VOOLT==='function'?VOOLT(k):k;}
function el(tag,text){var n=document.createElement(tag);if(text!==undefined)n.textContent=text;return n;}
function label(parent,key,type,value){var l=el('label',t(key)),n=el(type==='textarea'?'textarea':type==='select'?'select':'input');if(type!=='textarea'&&type!=='select')n.type=type||'text';if(type==='checkbox'){l.className='vl-check';l.prepend(n);}else l.appendChild(n);if(value!==undefined)n.value=value;parent.appendChild(l);return n;}
function cap(k){return t('lend.cap_'+k);}
function errorText(code){if(code==='CAPABILITY_UNAVAILABLE')return t('lend.unavailable');if(['EXPIRED','REVOKED','USED_UP','TIMEOUT','HOST_NOT_CONFIRMED','INPUT_CHANGED','INPUT_TOO_BIG'].includes(code)){var keys={EXPIRED:'expired',REVOKED:'revoked',USED_UP:'used_up',TIMEOUT:'timeout',HOST_NOT_CONFIRMED:'confirming',INPUT_CHANGED:'file_changed',INPUT_TOO_BIG:'size_error'};return t('lend.'+keys[code]);}if(['WRONG_FINGERPRINT','IDENTITY_MISMATCH','FINGERPRINT_CONFIRMATION_REQUIRED'].includes(code))return t('drop.pin_error');if(['DROP_DISABLED','LEND_DISABLED'].includes(code))return t('lend.need_drop');return t('lend.error');}
function stateText(state){var shared={pending:'activity.ev.permission_required',waiting_approval:'lend.submitted',declined:'xact.state_declined',complete:'run.complete'};return t(shared[state]||'lend.'+state);}
async function request(action,values,timeout,door){var control=new AbortController(),timer=setTimeout(function(){control.abort();},timeout||15000);try{var response=await fetch('/api/'+(door||'lend'),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.assign({action:action},values||{})),signal:control.signal});var value=await response.json();if(!response.ok||!value.ok)throw {code:value.error};return value;}finally{clearTimeout(timer);}}
function fileSize(value){var unit=value>=1000000?'MB':'KB',amount=value/(unit==='MB'?1000000:1000);return amount.toLocaleString(document.documentElement.lang,{maximumFractionDigits:2})+' '+unit;}
function receiptView(parent,job,value){var receipt=job.receipt,details=el('details');details.className='vl-receipt';details.appendChild(el('summary',t('lend.receipt')));var main=el('div');main.className='vl-receipt-main';main.appendChild(el('p',stateText(receipt.state)));main.appendChild(el('p',job.name+' · '+fileSize(job.size)));if(value)main.appendChild(el('p',cap(value.terms.capability)));main.appendChild(el('p',t('proof.elapsed')+': '+(receipt.seconds===null?t('addons.unknown'):receipt.seconds.toLocaleString(document.documentElement.lang)+' s')));main.appendChild(el('p',new Date(receipt.finished).toLocaleString(document.documentElement.lang)));details.appendChild(main);var hashes=el('details');hashes.className='vl-receipt-digests';hashes.appendChild(el('summary','SHA-256'));hashes.appendChild(el('pre',t('lend.terms')+'\n'+receipt.terms_digest+'\n'+t('drop.file')+'\n'+receipt.input_digest+'\n'+t('settings.nav.results')+'\n'+(receipt.result_digest||'')));details.appendChild(hashes);parent.appendChild(details);}
function summary(parent,value){parent.textContent='';var dl=el('dl');[['lend.terms',cap(value.capability)],['lend.count',String(value.jobs)],['lend.size',fileSize(value.max_bytes)],['lend.length',String(value.max_length)],['lend.seconds',String(value.max_seconds)],['drop.expiry',new Date(value.expires).toLocaleString(document.documentElement.lang)],['lend.auto',t(value.auto?'plugins.status.on':'plugins.status.off')]].concat(value.capability==='recording'?[['lend.trim_start',String(value.trim_start)],['lend.trim_length',String(value.trim_length)]]:[]).forEach(function(row){dl.appendChild(el('dt',t(row[0])));dl.appendChild(el('dd',row[1]));});parent.appendChild(dl);parent.appendChild(el('p',t('lend.local_only')));}
function peerInfo(parent,pin){var row=el('div');row.appendChild(el('span',t('drop.peer')+': '));var code=el('code',pin);code.dir='ltr';code.className='vl-peer-pin';row.appendChild(code);parent.appendChild(row);}
function termsDetails(parent,value){var detail=el('details'),body=el('div');detail.appendChild(el('summary',t('lend.terms')));summary(body,value);detail.appendChild(body);parent.appendChild(detail);}
window.VoolLend={mountInto:function(host){
 var root=el('section');root.className='vl-root';host.appendChild(root);var busy=false,refreshing=false,config=null,preview=null,chosen='',snapshot=null,mode='host',editing=false;
 root.appendChild(el('div',t('lend.warning'))).className='vl-warning';
 var enabled=label(root,'lend.title','checkbox');enabled.className='vl-enable';
 var status=el('div');status.className='vl-status';status.setAttribute('role','status');root.appendChild(status);
 function control(key){return key==='lend.revoke'||key==='notif.save';}
 function setBusy(value){busy=value;root.setAttribute('aria-busy',String(value));root.querySelectorAll('button[data-vl-action]').forEach(function(b){if(value&&!control(b.dataset.vlAction)&&!b.disabled){b.dataset.vlBusy='1';b.disabled=true;}else if(!value&&b.dataset.vlBusy){delete b.dataset.vlBusy;b.disabled=false;}});}
 function button(parent,key,work){var b=el('button',t(key));b.type='button';b.className='btn';b.dataset.vlAction=key;if(busy&&!control(key)){b.disabled=true;b.dataset.vlBusy='1';}parent.appendChild(b);b.onclick=async function(){var held=!busy;if(busy&&!control(key))return;if(held)setBusy(true);b.disabled=true;status.textContent='';try{await work();}catch(e){status.textContent=errorText(e.code);}finally{if(held)setBusy(false);b.disabled=false;selectBorrow();if(config)createInvite.disabled=!config.capabilities[capability.value];}};return b;}
 button(root,'notif.save',async function(){try{await request('settings',{enabled:enabled.checked});}catch(e){await load();throw e;}await load();});
 var panel=el('div');panel.className='vl-root';panel.hidden=true;root.appendChild(panel);
 var identity=label(panel,'drop.fingerprint','text');identity.readOnly=true;identity.dir='ltr';identity.className='vl-identity';
 var peer=label(panel,'drop.peer','text');peer.className='vl-peer';peer.dir='ltr';peer.autocomplete='off';
 var pinned=label(panel,'drop.check','checkbox');pinned.className='vl-pinned';peer.oninput=function(){pinned.checked=false;};
 var modes=el('div');modes.className='vl-actions';panel.appendChild(modes);var hostMode=button(modes,'lend.host',async function(){mode='host';applyMode();}),guestMode=button(modes,'lend.guest',async function(){mode='guest';applyMode();});hostMode.classList.add('vl-mode');guestMode.classList.add('vl-mode');var hostBox=el('fieldset');hostBox.appendChild(el('legend',t('lend.host')));panel.appendChild(hostBox);
 var capability=label(hostBox,'lend.terms','select');capability.className='vl-capability';
 var grid=el('div');grid.className='vl-grid';hostBox.appendChild(grid);
 var count=label(grid,'lend.count','number','1');count.min='1';count.max='10';count.className='vl-count';
 var size=label(grid,'lend.size','number','10');size.min='0.001';size.max='10';size.step='0.001';size.className='vl-size';
 var length=label(grid,'lend.length','number','50000');length.min='1';length.max='250000';length.className='vl-length';
 var seconds=label(grid,'lend.seconds','number','30');seconds.min='1';seconds.max='120';seconds.className='vl-seconds';
 var expiry=label(grid,'drop.expiry','datetime-local');expiry.className='vl-expiry';
 var start=label(grid,'lend.trim_start','number','0');start.min='0';start.max='3600';
 var duration=label(grid,'lend.trim_length','number','30');duration.min='1';duration.max='300';
 var auto=label(hostBox,'lend.auto','checkbox');auto.className='vl-auto';
 var offer=el('textarea');offer.className='vl-offer';offer.readOnly=true;offer.dir='ltr';offer.hidden=true;offer.setAttribute('aria-label',t('drop.link'));hostBox.appendChild(offer);
 var qr=el('img');qr.width=360;qr.height=360;qr.alt=t('drop.link');qr.className='vl-qr';qr.hidden=true;hostBox.appendChild(qr);
 function offeredTerms(){return {capability:capability.value,jobs:Number(count.value),max_bytes:Math.floor(Number(size.value)*1000000),max_length:Number(length.value),max_seconds:Number(seconds.value),expires:new Date(expiry.value).getTime(),auto:auto.checked,local_only:true,trim_start:Number(start.value),trim_length:Number(duration.value)};}
 var createInvite=button(hostBox,'drop.invite',async function(){var j=await request('invite',{fingerprint:peer.value.trim(),confirmed:pinned.checked,terms:offeredTerms()});offer.value=j.link;offer.hidden=false;qr.src=j.qr;qr.hidden=false;await refresh();});
 capability.onchange=function(){createInvite.disabled=!(config&&config.capabilities[capability.value]);length.value=capability.value==='contact_sheet'?'20':capability.value==='recording'?'600':'50000';length.max=capability.value==='contact_sheet'?'100':capability.value==='recording'?'3600':'250000';start.parentElement.hidden=duration.parentElement.hidden=capability.value!=='recording';};
 var guestBox=el('fieldset');guestBox.appendChild(el('legend',t('lend.guest')));panel.appendChild(guestBox);
 guestBox.appendChild(el('p',t('lend.processor'))).className='vl-processor';
 var connectBox=el('div');connectBox.className='vl-root vl-connect';guestBox.appendChild(connectBox);var link=label(connectBox,'drop.link','textarea');link.maxLength=4096;link.dir='ltr';link.className='vl-link';
 var review=el('div');review.className='vl-review';review.hidden=true;connectBox.appendChild(review);
 var trusted=label(connectBox,'lend.trust','checkbox');trusted.className='vl-trust';trusted.disabled=true;
 link.oninput=function(){preview=null;review.hidden=true;trusted.checked=false;trusted.disabled=true;};
 button(connectBox,'lend.review',async function(){preview=await request('preview',{link:link.value.trim()});summary(review,preview.terms);review.appendChild(el('p',t('drop.peer')+': '+preview.host));review.hidden=false;trusted.checked=false;trusted.disabled=false;});
 button(connectBox,'notif.join',async function(){if(!preview||!trusted.checked)throw {code:'INVALID_INPUT'};chosen=(await request('join',{link:link.value.trim(),fingerprint:peer.value.trim(),confirmed:pinned.checked&&trusted.checked})).invite;editing=false;await refresh();});
 var newInvite=button(guestBox,'lend.review',async function(){editing=true;applyMode();});var borrowBox=el('div');borrowBox.className='vl-root vl-borrow-box';guestBox.appendChild(borrowBox);var borrow=label(borrowBox,'lend.terms','select');borrow.className='vl-borrow';
 var borrowed=el('div');borrowed.className='vl-borrowed';borrowBox.appendChild(borrowed);
 var file=label(borrowBox,'drop.file','file');file.className='vl-file';
 var send=button(borrowBox,'lend.send',async function(){var entry=(snapshot.invites||[]).find(function(v){return v.id===borrow.value;});if(!entry||entry.state!=='ready'||entry.used>=entry.terms.jobs||file.files.length!==1)throw {code:'HOST_NOT_CONFIRMED'};var selected=file.files[0];if(selected.size>entry.terms.max_bytes)throw {code:'INPUT_TOO_BIG'};var data=await selected.arrayBuffer();var hash=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',data))).map(function(x){return x.toString(16).padStart(2,'0');}).join('');var controller=new AbortController(),timer=setTimeout(function(){controller.abort();},120000);try{var r=await fetch('/api/lend/send',{method:'POST',headers:{'Content-Type':'application/octet-stream','X-Lend-Invite':entry.id,'X-Lend-Name':encodeURIComponent(selected.name),'X-Lend-Size':String(data.byteLength),'X-Lend-SHA256':hash,'X-Lend-Job':crypto.randomUUID().replace(/-/g,'')},body:data,signal:controller.signal});var j=await r.json();if(!r.ok||!j.ok)throw {code:j.error};file.value='';await refresh();}finally{clearTimeout(timer);}});
 function selectBorrow(){var value=snapshot&&(snapshot.invites||[]).find(function(v){return v.id===borrow.value;});borrowed.textContent='';send.disabled=true;file.disabled=true;if(!value)return;summary(borrowed,value.terms);peerInfo(borrowed,value.host);if(value.terms.capability==="clean_pdf")borrowed.appendChild(el("p",t("lend.formats_pdf")));file.accept=value.terms.capability==="contact_sheet"?".zip,.png,.jpg,.jpeg,.webp":value.terms.capability==="recording"?"audio/*,video/*":".txt,.md,.pdf,.docx";borrowed.appendChild(el('p',value.state==='ready'?(value.used>=value.terms.jobs?t('lend.used_up'):t('lend.confirmed')):stateText(value.state)));send.disabled=busy||!(value.state==='ready'&&value.used<value.terms.jobs);file.disabled=send.disabled;}
 borrow.onchange=selectBorrow;function applyMode(){var has=snapshot&&snapshot.invites.some(function(v){return v.role==='guest';});hostBox.hidden=mode!=='host';guestBox.hidden=mode!=='guest';connectBox.hidden=has&&!editing;borrowBox.hidden=!has||editing;newInvite.hidden=editing||!has;peer.parentElement.hidden=pinned.parentElement.hidden=mode==='guest'&&has&&!editing;hostMode.setAttribute('aria-pressed',String(mode==='host'));guestMode.setAttribute('aria-pressed',String(mode==='guest'));}
 button(panel,'lend.refresh',refresh);
 var cards=el('div');cards.className='vl-root vl-cards';panel.appendChild(cards);
 async function refresh(){if(refreshing||panel.hidden)return;refreshing=true;try{snapshot=await request('poll',{},135000);if(!root.isConnected)return;var prior=chosen||borrow.value;chosen='';borrow.textContent='';snapshot.invites.filter(function(v){return v.role==='guest';}).forEach(function(v){var o=el('option',cap(v.terms.capability)+' · '+v.host.slice(0,8));o.value=v.id;borrow.appendChild(o);});if(Array.from(borrow.options).some(function(o){return o.value===prior;}))borrow.value=prior;selectBorrow();applyMode();cards.textContent='';snapshot.invites.filter(function(v){return v.role==='host'&&!['expired','revoked'].includes(v.state);}).forEach(function(v){var card=el('div');card.className='vl-card';card.dataset.invite=v.id;card.appendChild(el('strong',cap(v.terms.capability)));peerInfo(card,v.guest);termsDetails(card,v.terms);card.appendChild(el('span',t('drop.expiry')+': '+new Date(v.terms.expires).toLocaleString(document.documentElement.lang)));button(card,'lend.revoke',async function(){await request('revoke',{invite:v.id});await refresh();});cards.appendChild(card);});snapshot.jobs.forEach(function(job){var value=snapshot.invites.find(function(v){return v.id===job.invite;}),card=el('article');card.className='vl-card';card.dataset.job=job.id;card.appendChild(el('strong',job.name));if(value){peerInfo(card,job.role==='host'?value.guest:value.host);termsDetails(card,value.terms);}card.appendChild(el('span',(value?cap(value.terms.capability)+' · ':'')+fileSize(job.size)));card.appendChild(el('div',stateText(job.state))).className='vl-job-state';var actions=el('div');actions.className='vl-actions';card.appendChild(actions);if(job.role==='host'&&job.state==='pending'){button(actions,'lend.run',async function(){await request('run',{job:job.id},(value.terms.max_seconds+10)*1000);await refresh();});button(actions,'xact.decline',async function(){await request('decline',{job:job.id});await refresh();});}if(job.role==='guest'&&job.state==='complete'&&value&&value.state==='ready'){button(actions,'lend.download',async function(){var j=await request('download',{job:job.id},30000);var bytes=Uint8Array.from(atob(j.data),function(x){return x.charCodeAt(0);});var url=URL.createObjectURL(new Blob([bytes],{type:j.name.endsWith('.pdf')?'application/pdf':'audio/wav'})),a=el('a');a.href=url;a.download=j.name;a.click();setTimeout(function(){URL.revokeObjectURL(url);},1000);});}if(job.receipt)receiptView(card,job,value);cards.appendChild(card);});}finally{refreshing=false;}}
 async function load(){config=await request('status');enabled.checked=config.enabled;panel.hidden=!(config.enabled&&config.drop_enabled);status.textContent=config.drop_enabled?'':t('lend.need_drop');if(panel.hidden){offer.value='';offer.hidden=true;qr.removeAttribute('src');qr.hidden=true;return;}var id=await request('identity',{},15000,'drop');identity.value=id.fingerprint;capability.textContent='';Object.keys(config.capabilities).forEach(function(key){var o=el('option',cap(key)+(config.capabilities[key]?'':' — '+t('lend.unavailable')));o.value=key;o.disabled=!config.capabilities[key];capability.appendChild(o);});capability.value='clean_pdf';var date=new Date(config.defaults.expires);expiry.value=new Date(date.getTime()-date.getTimezoneOffset()*60000).toISOString().slice(0,16);capability.onchange();await refresh();}
 load().catch(function(e){status.textContent=errorText(e.code);});
 var timer=setInterval(function(){if(!root.isConnected){clearInterval(timer);return;}if(!busy&&!panel.hidden)refresh().catch(function(e){status.textContent=errorText(e.code);});},5000);
return true;}};
})();
</script>'''
